# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer do
  it "refuses a higher-version snapshot that names another company for an existing row and leaves the row unchanged" do
    connection = ActiveRecord::Base.connection
    company_a = create(:company)
    company_b = create(:company)
    entry = create(:timesheet_entry, project: create(:project, client: create(:client, company: company_a)))
    connection.execute("UPDATE timesheet_entries SET company_id = #{company_a.id}, version = 1 WHERE id = #{entry.id}")
    row_before = connection.select_one("SELECT * FROM timesheet_entries WHERE id = #{entry.id}")
    expect(row_before["company_id"]).to eq(company_a.id)

    user_b = create(:user)
    create(:employment, company: company_b, user: user_b)
    project_b = create(:project, client: create(:client, company: company_b))
    snapshot_entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
      "id" => entry.id, "company_id" => company_b.id, "version" => 5, "project_id" => project_b.id,
      "user_id" => user_b.id, "work_date" => "2026-03-02", "duration" => 90.0, "note" => "moved",
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
      "source_metadata" => {}, "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z",
      "updated_at" => "2026-03-02T09:00:00Z"
    )
    batch = { "schema_version" => 1,
              "snapshots" => [{ "generation" => TimekeepingOwnership.current.generation, "outbox_position" => 1,
                                "entry" => snapshot_entry }] }

    result = described_class.call(batch:, idempotency_key: nil)

    # "A snapshot whose `company_id` differs from the row's is refused."
    expect(result.status).to eq(409)
    expect(result.body.deep_stringify_keys).to eq("reason" => "stale_generation")
    expect(connection.select_one("SELECT * FROM timesheet_entries WHERE id = #{entry.id}")).to eq(row_before)
  end
end

require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer do
  it "refuses a new snapshot for one company that names another company's project and writes no row" do
    company_a = create(:company)
    company_b = create(:company)
    user_a = create(:user)
    create(:employment, company: company_a, user: user_a)
    project_b = create(:project, client: create(:client, company: company_b))
    entry_id = 70_501
    snapshot_entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
      "id" => entry_id, "company_id" => company_a.id, "version" => 1, "project_id" => project_b.id,
      "user_id" => user_a.id, "work_date" => "2026-03-02", "duration" => 90.0, "note" => "company A private note",
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
      "source_metadata" => {}, "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z",
      "updated_at" => "2026-03-02T09:00:00Z"
    )
    batch = { "schema_version" => 1,
              "snapshots" => [{ "generation" => TimekeepingOwnership.current.generation, "outbox_position" => 1,
                                "entry" => snapshot_entry }] }

    result = described_class.call(batch:, idempotency_key: nil)

    # Company reports reach entries through clients and projects, so an entry filed under
    # another company's project would show in that company's reports.
    expect(result.status).to eq(422)
    expect(result.body.deep_stringify_keys).to eq("reason" => "invalid_snapshot")
    expect(TimesheetEntry.unscoped.where(id: entry_id)).to be_empty
    expect(company_b.timesheet_entries.where(note: "company A private note")).to be_empty
  end
end
